Pod::Spec.new do |s|
  s.name           = 'ExpoSpeechRecognizer'
  s.version        = '1.0.0'
  s.summary        = 'Local Speech recognition module'
  s.description    = 'Local Speech recognition module'
  s.author         = 'Nathan Walker'
  s.homepage       = 'https://docs.expo.dev/modules/'
  s.platforms      = {
    :ios => '16.4'
  }
  s.source         = { git: '' }
  s.static_framework = true

  s.dependency 'ExpoModulesCore'
  s.frameworks = 'Speech'

  # Swift/Objective-C compatibility
  s.pod_target_xcconfig = {
    'DEFINES_MODULE' => 'YES',
  }

  s.source_files = "**/*.{h,m,mm,swift,hpp,cpp}"
  s.resource_bundles = {
    'ExpoSpeechRecognizerAssets' => ['../../../spec-assets/sample.wav']
  }
end

